"use strict";

/**
 * Geofence Editor Validasyonu (locked, written before implementation per
 * WORKING_RULES.md "Mimari Baglam Zorunlulugu").
 *
 * Harita Dokumani v2 SS9.5:
 *   - Polygon en az 3 nokta olmadan kaydedilemez.
 *   - Circle radius: min 10m, max 5km.
 *   - Self-intersecting polygon engellenmeli.
 *
 * Do not edit this file to make it pass. Edit
 * routes/geofenceValidation.js.
 *
 * Run: node --test tests/geofenceValidation.test.js
 */

const test = require("node:test");
const assert = require("node:assert/strict");
const {
  validateCoordinatesShape,
  validateRadius,
  isSelfIntersectingPolygon,
  validateGeofencePayload,
} = require("../routes/geofenceValidation");

// ── validateCoordinatesShape ────────────────────────────────

test("validateCoordinatesShape: circle + gecerli {lat,lng} -> ok", () => {
  const r = validateCoordinatesShape("circle", { lat: 52.5, lng: 4.6 });
  assert.equal(r.ok, true);
});

test("validateCoordinatesShape: circle + eksik/gecersiz nokta -> red", () => {
  assert.equal(validateCoordinatesShape("circle", { lat: 52.5 }).ok, false);
  assert.equal(validateCoordinatesShape("circle", null).ok, false);
  assert.equal(
    validateCoordinatesShape("circle", { lat: "abc", lng: 4.6 }).ok,
    false
  );
  assert.equal(
    validateCoordinatesShape("circle", { lat: 200, lng: 4.6 }).ok,
    false
  ); // lat sinir disi
});

test("validateCoordinatesShape: polygon + 3+ nokta -> ok", () => {
  const r = validateCoordinatesShape("polygon", [
    { lat: 52.5, lng: 4.6 },
    { lat: 52.51, lng: 4.61 },
    { lat: 52.52, lng: 4.6 },
  ]);
  assert.equal(r.ok, true);
});

test("validateCoordinatesShape: polygon + 2 nokta -> red (min 3 kurali)", () => {
  const r = validateCoordinatesShape("polygon", [
    { lat: 52.5, lng: 4.6 },
    { lat: 52.51, lng: 4.61 },
  ]);
  assert.equal(r.ok, false);
  assert.match(r.error, /3/);
});

test("validateCoordinatesShape: polygon + array degil -> red", () => {
  assert.equal(
    validateCoordinatesShape("polygon", { lat: 52.5, lng: 4.6 }).ok,
    false
  );
});

test("validateCoordinatesShape: polygon + icinde gecersiz nokta -> red", () => {
  const r = validateCoordinatesShape("polygon", [
    { lat: 52.5, lng: 4.6 },
    { lat: 52.51, lng: 4.61 },
    { lat: "yanlis", lng: 4.6 },
  ]);
  assert.equal(r.ok, false);
});

// ── validateRadius ───────────────────────────────────────────

test("validateRadius: circle + 10m-5000m arasi -> ok", () => {
  assert.equal(validateRadius("circle", 10).ok, true);
  assert.equal(validateRadius("circle", 2500).ok, true);
  assert.equal(validateRadius("circle", 5000).ok, true);
});

test("validateRadius: circle + 10m altinda -> red", () => {
  const r = validateRadius("circle", 5);
  assert.equal(r.ok, false);
  assert.match(r.error, /10/);
});

test("validateRadius: circle + 5km ustunde -> red", () => {
  const r = validateRadius("circle", 6000);
  assert.equal(r.ok, false);
  assert.match(r.error, /5000/);
});

test("validateRadius: circle + radius yok/sayisal degil -> red", () => {
  assert.equal(validateRadius("circle", null).ok, false);
  assert.equal(validateRadius("circle", undefined).ok, false);
  assert.equal(validateRadius("circle", "abc").ok, false);
  assert.equal(validateRadius("circle", 0).ok, false); // 0 artik gecmiyor
});

test("validateRadius: polygon icin radius kontrolsuz gecer (uygulanmaz)", () => {
  assert.equal(validateRadius("polygon", null).ok, true);
});

// ── isSelfIntersectingPolygon ────────────────────────────────

test("isSelfIntersectingPolygon: basit (convex) dortgen -> false", () => {
  const square = [
    { lat: 0, lng: 0 },
    { lat: 0, lng: 1 },
    { lat: 1, lng: 1 },
    { lat: 1, lng: 0 },
  ];
  assert.equal(isSelfIntersectingPolygon(square), false);
});

test("isSelfIntersectingPolygon: kelebek/bowtie sekli (kenarlar kesisiyor) -> true", () => {
  // Klasik "bowtie": (0,0)-(1,1)-(0,1)-(1,0) -> ilk ve ucuncu kenar ortada kesisir
  const bowtie = [
    { lat: 0, lng: 0 },
    { lat: 1, lng: 1 },
    { lat: 0, lng: 1 },
    { lat: 1, lng: 0 },
  ];
  assert.equal(isSelfIntersectingPolygon(bowtie), true);
});

test("isSelfIntersectingPolygon: 3 nokta (ucgen) her zaman basit -> false", () => {
  const triangle = [
    { lat: 0, lng: 0 },
    { lat: 1, lng: 0 },
    { lat: 0, lng: 1 },
  ];
  assert.equal(isSelfIntersectingPolygon(triangle), false);
});

// ── validateGeofencePayload (entegrasyon) ────────────────────

test("validateGeofencePayload: gecerli circle -> ok", () => {
  const r = validateGeofencePayload({
    fence_type: "circle",
    coordinates: { lat: 52.5, lng: 4.6 },
    radius: 100,
  });
  assert.equal(r.ok, true);
});

test("validateGeofencePayload: gecerli polygon -> ok", () => {
  const r = validateGeofencePayload({
    fence_type: "polygon",
    coordinates: [
      { lat: 0, lng: 0 },
      { lat: 0, lng: 1 },
      { lat: 1, lng: 1 },
      { lat: 1, lng: 0 },
    ],
    radius: null,
  });
  assert.equal(r.ok, true);
});

test("validateGeofencePayload: self-intersecting polygon -> red", () => {
  const r = validateGeofencePayload({
    fence_type: "polygon",
    coordinates: [
      { lat: 0, lng: 0 },
      { lat: 1, lng: 1 },
      { lat: 0, lng: 1 },
      { lat: 1, lng: 0 },
    ],
    radius: null,
  });
  assert.equal(r.ok, false);
  assert.match(r.error, /kesi/i);
});

test("validateGeofencePayload: once shape, sonra radius, sonra self-intersection kontrol edilir (ilk hata donulur)", () => {
  // shape hatasi varsa radius/self-intersection kontrolune hic girilmemeli
  const r = validateGeofencePayload({
    fence_type: "polygon",
    coordinates: [{ lat: 0, lng: 0 }], // 1 nokta -> shape hatasi
    radius: 99999, // gecersiz radius olsa da ilgisiz, polygon icin kontrol edilmiyor zaten
  });
  assert.equal(r.ok, false);
  assert.match(r.error, /3/);
});
